import React, { useEffect, useState } from 'react';
import api from '../../services/api';

const imgUrl = (fn) => fn ? `https://localhost:7113/${fn}` : null;

const InfoRow = ({ label, value }) => (
  <div className="col-md-6 mb-2">
    <small className="text-muted d-block" style={{ fontSize: '0.72rem', letterSpacing: '0.04em', textTransform: 'uppercase' }}>{label}</small>
    <div className="fw-semibold text-dark" style={{ fontSize: '0.92rem' }}>{value || '—'}</div>
  </div>
);

const SectionLabel = ({ children }) => (
  <div style={{
    fontSize: '0.7rem',
    textTransform: 'uppercase',
    letterSpacing: '0.1em',
    color: '#6c757d',
    fontWeight: 600,
    marginBottom: 10,
    paddingBottom: 6,
    borderBottom: '1px solid #e9ecef',
  }}>
    {children}
  </div>
);

const OrderViewModal = ({ orderId, onClose }) => {
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [imgViewer, setImgViewer] = useState(null);
const [selected, setSelected] = useState(null);
  useEffect(() => {
    if (!orderId) return;
    setLoading(true);
    api.get(`https://localhost:7113/api/order/GetOrderView?orderID=${orderId}`)
      .then(r => setOrder(r.data[0]))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [orderId]);

  useEffect(() => {
    const handler = (e) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [onClose]);

  if (!orderId) return null;

  // Normalised field helper — handles both old camelCase and new snake_Case API shapes
  const get = (o) => {
    if (!o) return {};
    return {
      orderNumber:          o.order_Number          || o.orderNumber          || o.order__Number || orderId,
      orderDate:            o.order_Date            || o.orderDate,
      deliveryDate:         o.delivery_Date         || o.deliveryDate,
      customerName:         o.customer_Name         || o.customerId?.customerName,
      design:               o.design,
      quantity:             o.quantity,
      // karat / metal
      karat:                o.karat                 || o.kt,
      karatPercent:         o.karat_Percent,
      designType:           o.design_Type           || o.type,
      goldColour:           o.gold_Colour,
      size:                 o.size,
      weight:               o.weight                || o.goldWeight,
      // stone / diamond
      stoneName:            o.stone_Name,
      isColourRequired:     o.is_Colour_Required,
      colourStoneName:      o.colour_Stone_Name,
      colourStone:          o.colour_Stone,
      isCertRequired:       o.is_Certificate_Required,
      certificateName:      o.cretificate_Name      || o.certificateName,
      diamondQuality:       o.diamond_Quality,
      diamondWeight:        o.diamond_Weight        || o.diamondWeight,
      noOfDiamonds:         o.noOf_Diamonds         || o.numberOfDiamonds,
      noOfColourStone:      o.noOfColour_Stone,
      colourStoneWeight:    o.colourStone_Weight,
      othersNoOfCS:         o.others_NoOfColour_Stone,
      othersCSWeight:       o.others_Colour_Stone_Weight,
      // specification
      specification:        o.specification         || o.designSpecification,
      reworkSpec:           o.reworkSpecification,
      // designer stage
      designerWeight:       o.designer_Weight,
      designerDiamondWt:    o.designer_Diamond_Weight,
      designerNoOfDiamonds: o.designer_NoOf_Diamonds,
      // completion
      isOrderCompleted:     o.is_Order_Completed,
      orderCompleteDT:      o.order_Complete_DT,
      finalGrossWeight:     o.final_Gross_Weight    || o.finalGoldWeight,
      finalNetWeight:       o.final_Net_Weight,
      finalNoOfDiamonds:    o.final_Noof_Diamonds   || o.numberOfDiamonds,
      finalDiamondWeight:   o.final_Diamond_Weight  || o.finalDiamondWeight,
      gold24ktWeight:       o.gold24ktWeight,
      billAmount:           o.billAmount,
      // images
      frontImage:           o.front_Image_URL       || o.frontImage,
      topImage:             o.top_Image_URL         || o.topImage,
      sideImage:            o.side_Image_URL        || o.sideImage,
      backImage:            o.back_Image_URL        || o.backImage,
      cadImage:             o.caD_Image_URL         || o.cadImage,
      // flags
      isDesignApproved:     o.is_Design_Approved,
      status:               o.status,
    };
  };

  const d = get(order);

  const fmtDate = (val) => {
    if (!val) return null;
    const dt = new Date(val);
    return isNaN(dt) ? val : dt.toLocaleDateString('en-IN');
  };

  const customerImages = [
    { key: 'frontImage', label: 'Front' },
    { key: 'topImage',   label: 'Top'   },
    { key: 'sideImage',  label: 'Side'  },
    { key: 'backImage',  label: 'Back'  },
  ];
const renderActions = () => {
    if (!selected) return null;
    switch (selected.status) {
      case 'pending':
      case 'rework_requested':
        return (
          <div className="card mt-3">
            <div className="card-header fw-semibold">Assign to Designer</div>
            <div className="card-body">
              <div className="mb-3">
                <label className="form-label">Designer *</label>
                <select className="form-select" value={actionForm.designerId || ''}
                  onChange={e => setActionForm({ ...actionForm, designerId: e.target.value })}>
                  <option value="">Select Designer</option>
                  {designers.map(d => <option key={d._id} value={d._id}>{d.employeeName}</option>)}
                </select>
              </div>
              <div className="mb-3">
                <label className="form-label">Design Specification</label>
                <textarea className="form-control" rows={3} value={actionForm.designSpecification || ''}
                  onChange={e => setActionForm({ ...actionForm, designSpecification: e.target.value })} />
              </div>
              <button className="btn btn-primary" onClick={assignDesigner} disabled={loading}>Assign & Notify</button>
            </div>
          </div>
        );

      case 'design_uploaded':
        return (
          <div className="card mt-3">
            <div className="card-header fw-semibold">Review CAD Design</div>
            <div className="card-body">
              <div className="row g-2 mb-3">
                <div className="col">
                  <label className="form-label">Diamond Weight</label>
                  <input type="number" step="0.01" className="form-control" value={actionForm.diamondWeight || ''}
                    onChange={e => setActionForm({ ...actionForm, diamondWeight: e.target.value })} />
                </div>
                <div className="col">
                  <label className="form-label">No. of Stones</label>
                  <input type="number" className="form-control" value={actionForm.numberOfStones || ''}
                    onChange={e => setActionForm({ ...actionForm, numberOfStones: e.target.value })} />
                </div>
              </div>
              <div className="d-flex gap-2">
                <button className="btn btn-success" onClick={() => confirmDesign(true)} disabled={loading}>
                  ✅ Confirm Design
                </button>
                <button className="btn btn-warning" onClick={() => {
                  const spec = prompt('Enter redesign specification:');
                  if (spec) { setActionForm({ ...actionForm, redesignSpecification: spec }); confirmDesign(false); }
                }} disabled={loading}>
                  🔄 Request Redesign
                </button>
              </div>
            </div>
          </div>
        );

      case 'customer_confirmed':
        return (
          <div className="card mt-3">
            <div className="card-header fw-semibold">Assign to Development</div>
            <div className="card-body">
              <div className="mb-3">
                <label className="form-label">Team Email</label>
                <input type="email" className="form-control" value={actionForm.teamEmail || ''}
                  onChange={e => setActionForm({ ...actionForm, teamEmail: e.target.value })} />
              </div>
              <button className="btn btn-primary" onClick={assignDevelopment} disabled={loading}>
                Assign to Development Team
              </button>
            </div>
          </div>
        );

      case 'under_processing':
        return (
          <div className="card mt-3">
            <div className="card-header fw-semibold">Complete Order</div>
            <div className="card-body">
              <div className="row g-2">
                {[
                  { key: 'finalGoldWeight', label: 'Final Gold Weight *' },
                  { key: 'finalDiamondWeight', label: 'Final Diamond Weight' },
                  { key: 'numberOfDiamonds', label: 'No. of Diamonds' },
                  { key: 'billAmount', label: 'Bill Amount *' },
                  { key: 'gold24ktWeight', label: '24kt Gold Weight (Ledger)' }
                ].map(f => (
                  <div className="col-md-4" key={f.key}>
                    <label className="form-label small">{f.label}</label>
                    <input type="number" step="0.001" className="form-control form-control-sm"
                      value={actionForm[f.key] || ''}
                      onChange={e => setActionForm({ ...actionForm, [f.key]: e.target.value })} />
                  </div>
                ))}
              </div>
              <button className="btn btn-success mt-3" onClick={completeOrder} disabled={loading}>
                Mark as Completed
              </button>
            </div>
          </div>
        );

      default: return null;
    }
  };
  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        style={{
          position: 'fixed', inset: 0,
          background: 'rgba(15, 23, 42, 0.55)',
          backdropFilter: 'blur(3px)',
          zIndex: 1050,
        }}
      />

      {/* Modal Panel */}
      <div style={{
        position: 'fixed',
        top: '50%', left: '50%',
        transform: 'translate(-50%, -50%)',
        width: 'min(820px, 96vw)',
        maxHeight: '90vh',
        background: '#fff',
        borderRadius: 16,
        boxShadow: '0 24px 64px rgba(0,0,0,0.22)',
        zIndex: 1051,
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden',
      }}>

        {/* Header */}
        <div style={{
          padding: '18px 24px',
          borderBottom: '1px solid #e9ecef',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
          background: '#f8f9fb',
        }}>
          <div>
            <span style={{ fontSize: '0.72rem', textTransform: 'uppercase', letterSpacing: '0.08em', color: '#6c757d' }}>Order Details</span>
            <h6 className="mb-0 fw-bold mt-1" style={{ fontSize: '1rem' }}>
              {order ? `#${d.orderNumber}` : '—'}
            </h6>
          </div>
          <div className="d-flex align-items-center gap-3">
            {d.status && (
              <span className={`badge rounded-pill px-3 py-2 ${
                d.status === 'completed' ? 'bg-success' :
                d.status === 'cancelled' ? 'bg-danger'  :
                d.status === 'pending'   ? 'bg-warning text-dark' : 'bg-primary'
              }`} style={{ fontSize: '0.75rem' }}>
                {d.status.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())}
              </span>
            )}
            {d.isOrderCompleted && (
              <span className="badge rounded-pill bg-success px-3 py-2" style={{ fontSize: '0.75rem' }}>Completed</span>
            )}
            {d.isDesignApproved && (
              <span className="badge rounded-pill bg-info text-dark px-3 py-2" style={{ fontSize: '0.75rem' }}>Design Approved</span>
            )}
            <button
              onClick={onClose}
              style={{
                background: 'none', border: 'none', cursor: 'pointer',
                width: 32, height: 32, borderRadius: '50%',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: '#6c757d', fontSize: '1.1rem',
                transition: 'background 0.15s',
              }}
              onMouseEnter={e => e.currentTarget.style.background = '#e9ecef'}
              onMouseLeave={e => e.currentTarget.style.background = 'none'}
              aria-label="Close"
            >✕</button>
          </div>
        </div>

        {/* Body */}
        <div style={{ overflowY: 'auto', padding: '24px', flex: 1 }}>
          {loading ? (
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status" />
              <div className="mt-2 text-muted small">Loading order…</div>
            </div>
          ) : !order ? (
            <div className="text-center py-5 text-muted">Failed to load order details.</div>
          ) : (
            <>
              {/* Customer & Order */}
              <div className="mb-4">
                <SectionLabel>Customer &amp; Order</SectionLabel>
                <div className="row g-0">
                  {d.customerName && <InfoRow label="Customer"      value={d.customerName} />}
                  <InfoRow label="Order Date"    value={fmtDate(d.orderDate)} />
                  <InfoRow label="Delivery Date" value={fmtDate(d.deliveryDate)} />
                  <InfoRow label="Design"        value={d.design} />
                  <InfoRow label="Quantity"      value={d.quantity} />
                  <InfoRow label="Size"          value={d.size} />
                </div>
              </div>

              {/* Metal Details */}
              <div className="mb-4">
                <SectionLabel>Metal Details</SectionLabel>
                <div className="row g-0">
                  <InfoRow label="Karat"       value={d.karat} />
                  <InfoRow label="Karat %"     value={d.karatPercent} />
                  <InfoRow label="Design Type" value={d.designType} />
                  <InfoRow label="Gold Colour" value={d.goldColour} />
                  <InfoRow label="Weight (g)"  value={d.weight} />
                </div>
              </div>

              {/* Stone & Diamond */}
              <div className="mb-4">
                <SectionLabel>Stone &amp; Diamond Details</SectionLabel>
                <div className="row g-0">
                  <InfoRow label="Stone Name"          value={d.stoneName} />
                  <InfoRow label="Diamond Quality"     value={d.diamondQuality} />
                  <InfoRow label="Diamond Weight"      value={d.diamondWeight} />
                  <InfoRow label="No. of Diamonds"     value={d.noOfDiamonds} />
                  {d.isColourRequired && (
                    <>
                      <InfoRow label="Colour Stone"          value={d.colourStoneName || d.colourStone} />
                      <InfoRow label="No. of Colour Stones"  value={d.noOfColourStone} />
                      <InfoRow label="Colour Stone Weight"   value={d.colourStoneWeight} />
                    </>
                  )}
                  {(d.othersNoOfCS || d.othersCSWeight) && (
                    <>
                      <InfoRow label="Others – No. of CS" value={d.othersNoOfCS} />
                      <InfoRow label="Others – CS Weight" value={d.othersCSWeight} />
                    </>
                  )}
                </div>
              </div>

              {/* Certificate */}
              {d.isCertRequired && (
                <div className="mb-4">
                  <SectionLabel>Certificate</SectionLabel>
                  <div className="row g-0">
                    <InfoRow label="Certificate Name" value={d.certificateName || 'Required'} />
                  </div>
                </div>
              )}

              {/* Specifications */}
              {(d.specification || d.reworkSpec) && (
                <div className="mb-4">
                  <SectionLabel>Specifications</SectionLabel>
                  {d.specification && (
                    <div className="alert alert-info py-2 mb-2">
                      <small><strong>Specification:</strong> {d.specification}</small>
                    </div>
                  )}
                  {d.reworkSpec && (
                    <div className="alert alert-warning py-2">
                      <small><strong>Rework Spec:</strong> {d.reworkSpec}</small>
                    </div>
                  )}
                </div>
              )}

              {/* Designer Stage */}
              {(d.designerWeight || d.designerDiamondWt || d.designerNoOfDiamonds) && (
                <div className="mb-4">
                  <SectionLabel>Designer Stage</SectionLabel>
                  <div className="row g-0">
                    <InfoRow label="Designer Weight"         value={d.designerWeight} />
                    <InfoRow label="Designer Diamond Wt."    value={d.designerDiamondWt} />
                    <InfoRow label="Designer No. Diamonds"   value={d.designerNoOfDiamonds} />
                  </div>
                </div>
              )}

              {/* Completion Details */}
              {(d.finalGrossWeight || d.finalNetWeight || d.billAmount || d.orderCompleteDT) && (
                <div className="mb-4">
                  <SectionLabel>Completion Details</SectionLabel>
                  <div className="row g-0">
                    <InfoRow label="Final Gross Weight"    value={d.finalGrossWeight} />
                    <InfoRow label="Final Net Weight"      value={d.finalNetWeight} />
                    <InfoRow label="24kt Gold Weight"      value={d.gold24ktWeight} />
                    <InfoRow label="Final No. of Diamonds" value={d.finalNoOfDiamonds} />
                    <InfoRow label="Final Diamond Weight"  value={d.finalDiamondWeight} />
                    <InfoRow label="Completed On"          value={fmtDate(d.orderCompleteDT)} />
                    {d.billAmount && (
                      <InfoRow label="Bill Amount" value={`₹ ${Number(d.billAmount).toLocaleString('en-IN')}`} />
                    )}
                  </div>
                </div>
              )}

              {/* CAD Image */}
              {imgUrl(d.cadImage) && (
                <div className="mb-4">
                  <SectionLabel>CAD Design</SectionLabel>
                  <img
                    src={imgUrl(d.cadImage)}
                    alt="CAD Design"
                    className="rounded"
                    style={{ maxHeight: 220, cursor: 'zoom-in', objectFit: 'contain', border: '1px solid #e9ecef' }}
                    onClick={() => setImgViewer(imgUrl(d.cadImage))}
                  />
                </div>
              )}

              {/* Customer Images */}
              {customerImages.some(({ key }) => imgUrl(d[key])) && (
                <div className="mb-2">
                  <SectionLabel>Customer Images</SectionLabel>
                  <div className="d-flex gap-2 flex-wrap">
                    {customerImages.map(({ key, label }) => imgUrl(d[key]) && (
                      <div key={key} style={{ position: 'relative' }}>
                        <img
                          src={imgUrl(d[key])}
                          alt={label}
                          onClick={() => setImgViewer(imgUrl(d[key]))}
                          style={{
                            width: 90, height: 90,
                            objectFit: 'cover',
                            borderRadius: 10,
                            cursor: 'zoom-in',
                            border: '2px solid #e9ecef',
                            transition: 'border-color 0.15s',
                          }}
                          onMouseEnter={e => e.currentTarget.style.borderColor = '#0d6efd'}
                          onMouseLeave={e => e.currentTarget.style.borderColor = '#e9ecef'}
                        />
                        <span style={{
                          position: 'absolute', bottom: 4, left: 4,
                          background: 'rgba(0,0,0,0.55)', color: '#fff',
                          fontSize: '0.62rem', borderRadius: 4, padding: '1px 5px',
                        }}>{label}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </>
          )}
        </div>

        {/* Footer */}
        <div style={{
          padding: '14px 24px',
          borderTop: '1px solid #e9ecef',
          background: '#f8f9fb',
          display: 'flex', justifyContent: 'flex-end',
        }}>
          <button className="btn btn-sm btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>

      {/* Full-size image viewer */}
      {imgViewer && (
        <div
          onClick={() => setImgViewer(null)}
          style={{
            position: 'fixed', inset: 0,
            background: 'rgba(0,0,0,0.88)',
            zIndex: 1060,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            cursor: 'zoom-out',
          }}
        >
          <img src={imgViewer} alt="Full view" style={{ maxHeight: '90vh', maxWidth: '90vw', borderRadius: 8 }} />
        </div>
      )}
    </>
  );
};

export default OrderViewModal;
